import React, { useEffect, useMemo, useState } from "react";
import Navbar from "../../components/Navbar";
import { api, API_BASE } from "../../utils/api";
import { getUser } from "../../utils/auth";

const STATUS = ["ALL", "NEW", "SAFE", "SUSPICIOUS", "SCAM", "CLOSED"];
const SEVERITY = ["ALL", "LOW", "MEDIUM", "HIGH"];

export default function AdminDashboard() {
  const user = getUser();

  const [cases, setCases] = useState([]);
  const [users, setUsers] = useState([]);

  const [status, setStatus] = useState("ALL");
  const [severity, setSeverity] = useState("ALL");
  const [q, setQ] = useState("");

  const [selected, setSelected] = useState(null);

  const [creating, setCreating] = useState(false);
  const [newUser, setNewUser] = useState({
    name: "",
    email: "",
    password: "",
    role: "ANALYST"
  });

  async function loadCases() {
    const res = await api.get("/api/admin/cases", {
      params: { status, severity, q }
    });
    setCases(res.data);
  }

  async function loadUsers() {
    try {
      const res = await api.get("/api/admin/users");
      setUsers(res.data);
    } catch {
      // analyst cannot view users
    }
  }

  useEffect(() => {
    loadCases();
    loadUsers();
    // eslint-disable-next-line
  }, []);

  useEffect(() => {
    loadCases();
    // eslint-disable-next-line
  }, [status, severity]);

  const filtered = useMemo(() => cases, [cases]);

  async function openCase(c) {
    const res = await api.get(`/api/admin/cases/${c._id}`);
    setSelected(res.data);
  }

  async function updateSelected(patch) {
    if (!selected) return;

    await api.patch(`/api/admin/cases/${selected._id}`, patch);
    await loadCases();

    const res = await api.get(`/api/admin/cases/${selected._id}`);
    setSelected(res.data);
  }

  async function createUser() {
    setCreating(true);
    try {
      await api.post("/api/admin/users", newUser);
      setNewUser({ name: "", email: "", password: "", role: "ANALYST" });
      await loadUsers();
      alert("✅ Analyst created");
    } catch (err) {
      alert(err?.response?.data?.message || "Failed to create user");
    } finally {
      setCreating(false);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />

      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h2 className="text-3xl font-black">SOC Dashboard</h2>
            <div className="text-sm text-gray-600">
              Logged in as: <b>{user?.name}</b> ({user?.role})
            </div>
          </div>

          <div className="flex gap-2 flex-wrap">
            <select
              className="border rounded-xl px-3 py-2"
              value={status}
              onChange={(e) => setStatus(e.target.value)}
            >
              {STATUS.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>

            <select
              className="border rounded-xl px-3 py-2"
              value={severity}
              onChange={(e) => setSeverity(e.target.value)}
            >
              {SEVERITY.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>

            <input
              className="border rounded-xl px-3 py-2"
              placeholder="Search (ticket/name/phone)"
              value={q}
              onChange={(e) => setQ(e.target.value)}
            />

            <button
              className="px-4 py-2 rounded-xl bg-gray-900 text-white"
              onClick={loadCases}
            >
              Search
            </button>
          </div>
        </div>

        <div className="grid lg:grid-cols-3 gap-6 mt-8">
          {/* Left list */}
          <div className="lg:col-span-1 bg-white rounded-3xl shadow p-4">
            <div className="font-bold mb-3">Cases</div>

            <div className="space-y-3 max-h-[70vh] overflow-auto pr-1">
              {filtered.map((c) => (
                <button
                  key={c._id}
                  onClick={() => openCase(c)}
                  className="w-full text-left border rounded-2xl p-4 hover:bg-gray-50"
                >
                  <div className="flex items-center justify-between">
                    <div className="font-bold">{c.ticketId}</div>
                    <div className="text-xs font-semibold">
                      {c.status} • {c.severity}
                    </div>
                  </div>

                  <div className="text-sm text-gray-700 mt-1">
                    {c.fullName} • {c.phone}
                  </div>

                  <div className="text-xs text-gray-500 mt-1">
                    {new Date(c.createdAt).toLocaleString()}
                  </div>
                </button>
              ))}

              {filtered.length === 0 && (
                <div className="text-sm text-gray-500">No cases found.</div>
              )}
            </div>
          </div>

          {/* Right details */}
          <div className="lg:col-span-2 bg-white rounded-3xl shadow p-6">
            {!selected ? (
              <div className="text-gray-600">Select a case to view details.</div>
            ) : (
              <div className="space-y-4">
                <div className="flex flex-wrap items-center justify-between gap-3">
                  <div>
                    <div className="text-2xl font-black">{selected.ticketId}</div>
                    <div className="text-sm text-gray-600">
                      {selected.fullName} • {selected.phone} •{" "}
                      {selected.category}
                    </div>
                  </div>

                  <div className="flex gap-2 flex-wrap">
                    <select
                      className="border rounded-xl px-3 py-2"
                      value={selected.status}
                      onChange={(e) =>
                        updateSelected({ status: e.target.value })
                      }
                    >
                      {STATUS.filter((s) => s !== "ALL").map((s) => (
                        <option key={s} value={s}>
                          {s}
                        </option>
                      ))}
                    </select>

                    <select
                      className="border rounded-xl px-3 py-2"
                      value={selected.severity}
                      onChange={(e) =>
                        updateSelected({ severity: e.target.value })
                      }
                    >
                      {SEVERITY.filter((s) => s !== "ALL").map((s) => (
                        <option key={s} value={s}>
                          {s}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="border rounded-2xl p-4">
                  <div className="font-bold">User Message</div>
                  <div className="text-sm text-gray-700 mt-2 whitespace-pre-wrap">
                    {selected.message}
                  </div>

                  {selected.link && (
                    <div className="mt-3 text-sm">
                      <span className="font-semibold">Link:</span>{" "}
                      <a
                        className="text-blue-600 underline"
                        href={selected.link}
                        target="_blank"
                        rel="noreferrer"
                      >
                        {selected.link}
                      </a>
                    </div>
                  )}

                  {selected.upiId && (
                    <div className="mt-2 text-sm">
                      <span className="font-semibold">UPI ID:</span>{" "}
                      {selected.upiId}
                    </div>
                  )}

                  {selected.suspectNumber && (
                    <div className="mt-2 text-sm">
                      <span className="font-semibold">Suspect Number:</span>{" "}
                      {selected.suspectNumber}
                    </div>
                  )}

                  {selected.screenshotUrl && (
                    <div className="mt-4">
                      <div className="font-semibold text-sm">Screenshot:</div>
                      <img
                        alt="screenshot"
                        className="mt-2 rounded-2xl border max-h-[350px]"
                        src={`${API_BASE}${selected.screenshotUrl}`}
                      />
                    </div>
                  )}
                </div>

                <div className="grid md:grid-cols-2 gap-4">
                  <div className="border rounded-2xl p-4">
                    <div className="font-bold">Analyst Reply (User)</div>
                    <textarea
                      className="mt-2 w-full border rounded-2xl p-3 min-h-[140px]"
                      value={selected.analystReply || ""}
                      onChange={(e) =>
                        setSelected({
                          ...selected,
                          analystReply: e.target.value
                        })
                      }
                      placeholder="Write user-facing reply..."
                    />

                    <div className="flex gap-2 flex-wrap mt-3">
                      <button
                        className="px-4 py-2 rounded-xl bg-gray-900 text-white"
                        onClick={() =>
                          updateSelected({ analystReply: selected.analystReply })
                        }
                      >
                        Save Reply
                      </button>

                      <button
                        className="px-4 py-2 rounded-xl border"
                        onClick={() =>
                          setSelected({
                            ...selected,
                            analystReply:
                              "✅ Status: SAFE\nThis looks genuine based on the information shared.\nStill, avoid sharing OTP/password and double-check official sources."
                          })
                        }
                      >
                        SAFE Template
                      </button>

                      <button
                        className="px-4 py-2 rounded-xl border"
                        onClick={() =>
                          setSelected({
                            ...selected,
                            analystReply:
                              "⚠️ Status: SUSPICIOUS\nDo NOT click further or make payment.\nPlease share full URL and sender details for confirmation."
                          })
                        }
                      >
                        SUSPICIOUS Template
                      </button>

                      <button
                        className="px-4 py-2 rounded-xl border"
                        onClick={() =>
                          setSelected({
                            ...selected,
                            analystReply:
                              "❌ Status: SCAM CONFIRMED\nThis is a known scam pattern.\nAction now:\n1) Block the sender\n2) Do NOT share OTP\n3) Report on the platform\nIf money is lost, contact bank + dial 1930 immediately."
                          })
                        }
                      >
                        SCAM Template
                      </button>
                    </div>
                  </div>

                  <div className="border rounded-2xl p-4">
                    <div className="font-bold">Internal Notes</div>
                    <textarea
                      className="mt-2 w-full border rounded-2xl p-3 min-h-[140px]"
                      value={selected.internalNotes || ""}
                      onChange={(e) =>
                        setSelected({
                          ...selected,
                          internalNotes: e.target.value
                        })
                      }
                      placeholder="SOC notes for team..."
                    />

                    <button
                      className="mt-3 px-4 py-2 rounded-xl bg-gray-900 text-white"
                      onClick={() =>
                        updateSelected({
                          internalNotes: selected.internalNotes
                        })
                      }
                    >
                      Save Notes
                    </button>
                  </div>
                </div>

                {/* Admin only: create analysts */}
                {user?.role === "ADMIN" && (
                  <div className="border rounded-2xl p-4">
                    <div className="font-bold">Create Analyst</div>

                    <div className="grid md:grid-cols-4 gap-3 mt-3">
                      <input
                        className="border rounded-xl px-3 py-2"
                        placeholder="Name"
                        value={newUser.name}
                        onChange={(e) =>
                          setNewUser({ ...newUser, name: e.target.value })
                        }
                      />

                      <input
                        className="border rounded-xl px-3 py-2"
                        placeholder="Email"
                        value={newUser.email}
                        onChange={(e) =>
                          setNewUser({ ...newUser, email: e.target.value })
                        }
                      />

                      <input
                        className="border rounded-xl px-3 py-2"
                        placeholder="Password"
                        type="password"
                        value={newUser.password}
                        onChange={(e) =>
                          setNewUser({ ...newUser, password: e.target.value })
                        }
                      />

                      <select
                        className="border rounded-xl px-3 py-2"
                        value={newUser.role}
                        onChange={(e) =>
                          setNewUser({ ...newUser, role: e.target.value })
                        }
                      >
                        <option value="ANALYST">ANALYST</option>
                        <option value="ADMIN">ADMIN</option>
                      </select>
                    </div>

                    <button
                      disabled={creating}
                      className="mt-3 px-4 py-2 rounded-xl bg-gray-900 text-white disabled:opacity-60"
                      onClick={createUser}
                    >
                      {creating ? "Creating..." : "Create User"}
                    </button>

                    <div className="text-xs text-gray-500 mt-2">
                      Admin can create multiple analysts for team.
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Users list */}
        {user?.role === "ADMIN" && (
          <div className="mt-8 bg-white rounded-3xl shadow p-6">
            <div className="font-bold">Users</div>

            <div className="mt-4 overflow-auto">
              <table className="min-w-[700px] w-full text-sm">
                <thead>
                  <tr className="text-left text-gray-600">
                    <th className="py-2">Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Status</th>
                    <th>Created</th>
                    <th></th>
                  </tr>
                </thead>

                <tbody>
                  {users.map((u) => (
                    <tr key={u._id} className="border-t">
                      <td className="py-2 font-semibold">{u.name}</td>
                      <td>{u.email}</td>
                      <td>{u.role}</td>
                      <td>{u.isActive ? "Active" : "Disabled"}</td>
                      <td>{new Date(u.createdAt).toLocaleDateString()}</td>

                      <td className="text-right">
                        <button
                          className="px-3 py-1 rounded-xl border"
                          onClick={async () => {
                            await api.patch(`/api/admin/users/${u._id}/toggle`);
                            await loadUsers();
                          }}
                        >
                          Toggle
                        </button>
                      </td>
                    </tr>
                  ))}

                  {users.length === 0 && (
                    <tr>
                      <td className="py-3 text-gray-500" colSpan="6">
                        No users found.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
